from pathlib import Path
import numpy as np,trimesh,json,hashlib
P=Path(__file__).parent;Q=P.parent/'final';d=np.load(Q/'eye-solution.npz');a={k:d[k] for k in d.files};v=a['after'].copy();old=v.copy();f=a['triangles'];tri=9861;ids=f[tri];neighbors=np.flatnonzero(np.isin(f,ids).any(1));neighbors=neighbors[neighbors!=tri];n=np.cross(v[f[:,1]]-v[f[:,0]],v[f[:,2]]-v[f[:,0]]);nt=n[neighbors].sum(0);edge=v[ids[2]]-v[ids[0]];el=np.linalg.norm(edge);u=edge/el;nt-=u*np.dot(nt,u);nt/=np.linalg.norm(nt)
