if np.dot(nt,bn[tri])<0:nt=-nt
transverse=np.cross(u,nt);t=np.dot(v[ids[1]]-v[ids[0]],u);v[ids[1]]=v[ids[0]]+u*t+transverse*height
extra=v-old;a['after']=v;a['sliver_tangent_delta']=extra;a['sliver_repair_delta']=a['sliver_repair_delta']+extra;a['sliver_repair_vertices']=np.linalg.norm(a['sliver_repair_delta'],axis=1)>0
np.savez_compressed(P/'eye-solution.npz',**a);trimesh.Trimesh(v,f,process=False).export(P/'eye-candidate.stl')
newn=np.cross(v[f[:,1]]-v[f[:,0]],v[f[:,2]]-v[f[:,0]]);dot=np.einsum('ij,ij->i',newn,bn)/(np.linalg.norm(newn,axis=1)*np.linalg.norm(bn,axis=1));r=json.loads((Q/'eye-solution-report.json').read_text());r['postprocess']['tangent_finish']={'method':'Single middle vertex of sliver9861 aligned with the smooth adjacent-face area-weighted normal, constrained to the plane containing the untouched two end vertices. Original triangle area retained.','vertex':int(ids[1]),'extra_delta_xyz_mm':extra[ids[1]].tolist(),'extra_length_mm':float(np.linalg.norm(extra[ids[1]])),'normal_dot_neighbor_tangent':float(np.dot(newn[tri]/np.linalg.norm(newn[tri]),nt))};r['Y_exact']=bool(np.array_equal(base[:,1],v[:,1]));r['maximum_Y_change_mm']=float(abs(v[:,1]-base[:,1]).max());r['normal_over90']=int((dot<0).sum());r['minimum_normal_dot']=float(dot.min());r['minimum_triangle_area_ratio']=float((np.linalg.norm(newn,axis=1)/np.linalg.norm(bn,axis=1)).min());r['solution_sha256']=hashlib.sha256((P/'eye-solution.npz').read_bytes()).hexdigest();r['candidate_stl_sha256']=hashlib.sha256((P/'eye-candidate.stl').read_bytes()).hexdigest();(P/'eye-solution-report.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r,indent=2))
